ssize_t WritePSDChannels(const PSDInfo *psd_info, const ImageInfo *image_info, Image *image, Image *next_image, MagickOffsetType size_offset, MagickBooleanType separate) {
  ssize_t bytes_written = 0;
  size_t number_pixels = 0;
  Quantum *compact_pixels = NULL;
  MagickOffsetType offset = 0;
  size_t length = 0;

  if (psd_info == (PSDInfo *) NULL) {
    return 0;
  }

  if (image == (Image *) NULL) {
    return 0;
  }

  if (image->pixels == (Quantum *) NULL) {
    return 0;
  }

  number_pixels = image->columns * image->rows;
  if (number_pixels == 0) {
    return 0;
  }

  if (next_image != (Image *) NULL) {
    switch (next_image->compression) {
      case NoCompression:
        compact_pixels = (Quantum *) AcquireQuantumMemory(number_pixels, sizeof(Quantum));
        if (compact_pixels == (Quantum *) NULL) {
          return 0;
        }
        break;
      default:
        break;
    }
  }

  switch (image->storage_class) {
    case DirectClass:
      switch (image->colorspace) {
        case RGBColorspace:
          length = WriteRGBChannels(psd_info, image_info, image, compact_pixels, separate);
          if (length == 0) {
            if (compact_pixels != (Quantum *) NULL) {
              compact_pixels = (Quantum *) RelinquishQuantumMemory(compact_pixels);
            }
            return 0;
          }
          bytes_written += length;
          offset += length;
          break;
        case CMYKColorspace:
          length = WriteCMYKChannels(psd_info, image_info, image, compact_pixels, separate);
          if (length == 0) {
            if (compact_pixels != (Quantum *) NULL) {
              compact_pixels = (Quantum *) RelinquishQuantumMemory(compact_pixels);
            }
            return 0;
          }
          bytes_written += length;
          offset += length;
          break;
        default:
          break;
      }
      break;
    default:
      break;
  }

  if (image->mask != (PixelInfo *) NULL) {
    length = WriteAlphaChannel(psd_info, image_info, image, compact_pixels, separate);
    if (length == 0) {
      if (compact_pixels != (Quantum *) NULL) {
        compact_pixels = (Quantum *) RelinquishQuantumMemory(compact_pixels);
      }
      return 0;
    }
    bytes_written += length;
    offset += length;
  }

  if (compact_pixels != (Quantum *) NULL) {
    compact_pixels = (Quantum *) RelinquishQuantumMemory(compact_pixels);
  }

  size_offset += offset;

  return bytes_written;
}
